function createPipe(x, z, h) {
  const g = new THREE.Group();
  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(1, 1, h, 32),
    new THREE.MeshStandardMaterial({ color: 0x00aa00, roughness: 0.3 })
  );
  body.position.y = h / 2;
  body.castShadow = true;
  body.receiveShadow = true;

  const rim = new THREE.Mesh(
    new THREE.CylinderGeometry(1.2, 1.2, 0.5, 32),
    new THREE.MeshStandardMaterial({ color: 0x00aa00, roughness: 0.3 })
  );
  rim.position.y = h;
  rim.castShadow = true;

  const hole = new THREE.Mesh(
    new THREE.CylinderGeometry(0.85, 0.85, 0.1, 32),
    new THREE.MeshStandardMaterial({ color: 0x1a3300 })
  );
  hole.position.y = h + 0.26;

  g.add(body, rim, hole);
  g.position.set(x, 0, z);
  return g;
}
scene.add(createPipe(-5, 0, 2));
scene.add(createPipe(8, -2, 2.5));

function makeQuestionTexture() {
  const c = document.createElement('canvas');
  c.width = 256;
  c.height = 256;
  const x = c.getContext('2d');
  x.fillStyle = '#f9a825';
  x.fillRect(0, 0, 256, 256);
  x.strokeStyle = '#f57f17';
  x.lineWidth = 16;
  x.strokeRect(8, 8, 240, 240);
  x.fillStyle = '#f57f17';
  x.beginPath(); x.arc(30, 30, 14, 0, Math.PI * 2); x.fill();
  x.beginPath(); x.arc(226, 30, 14, 0, Math.PI * 2); x.fill();
  x.beginPath(); x.arc(30, 226, 14, 0, Math.PI * 2); x.fill();
  x.beginPath(); x.arc(226, 226, 14, 0, Math.PI * 2); x.fill();
  x.fillStyle = '#ffffff';
  x.font = 'bold 140px sans-serif';
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.fillText('?', 128, 128);
  return new THREE.CanvasTexture(c);
}

