function createCloud(x, y, z, s) {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, flatShading: true });
  const p1 = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 16), mat);
  const p2 = new THREE.Mesh(new THREE.SphereGeometry(0.8, 16, 16), mat);
  p2.position.set(0.9, 0.1, 0);
  const p3 = new THREE.Mesh(new THREE.SphereGeometry(0.85, 16, 16), mat);
  p3.position.set(-0.8, 0.05, 0);
  g.add(p1, p2, p3);
  g.position.set(x, y, z);
  g.scale.setScalar(s);
  return g;
}
