let time = 0;
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = clock.getDelta();
  time += dt;

  coins.forEach((c, i) => {
    c.rotation.y += dt * 4;
    c.position.y = 2.2 + Math.sin(time * 3 + i * 1.2) * 0.15;
  });

  qBlock.position.y = 3.5 + Math.sin(time * 5) * 0.08;

  hero.position.y = -0.3 + Math.max(0, Math.sin(time * 3)) * 1.2;

  clouds.forEach((c, i) => {
    c.position.x += dt * (0.3 + i * 0.1);
    if (c.position.x > 30) c.position.x = -30;
  });

  const camAngle = time * 0.15;
  camera.position.x = Math.cos(camAngle) * 10;
  camera.position.z = Math.sin(camAngle) * 10;
  camera.position.y = 5 + Math.sin(time * 0.2) * 1;
  camera.lookAt(0, 2, 0);

  renderer.render(scene, camera);
}

